// Classroom interaction demo: no model requests, API credentials or paid credits.
const $=id=>document.getElementById(id);
function stop(){}
function showModal(html){const player=$('poetryPlayer');if(player)player.pause();$('modalBody').innerHTML=html;$('modal').showModal();$('modal').scrollTop=0;}
function openWork(id){location.href='index.html?work='+encodeURIComponent(id);}
const studioModes={image:{name:'画一幅诗境',cost:2,hint:'预览内置图片样例，同时保留你的提示词。'},video:{name:'拍一段意境',cost:6,hint:'预览内置影片与分镜参考，同时保留你的提示词。'},poem:{name:'和诗人唱和',cost:1,hint:'打开预写仿写范例，你可以继续修改成自己的表达。'}};
const studioProfiles=[
 {film:'lushan',work:'lb-lushan',title:'望庐山瀑布',scene:'晨光中的庐山，香炉峰升起紫色水雾，瀑布从岩壁落下，水光与天上银河相接',evidence:'“日照”“紫烟”“挂前川”“银河落九天”',emotion:'惊叹、开阔与自由',boundary:'把银河与瀑布相连属于诗意想象；“三千尺”不是测量值。',verse:'山光初染一溪晴，\n云散千峰落水声。\n欲借长风追白练，\n人间天上共澄明。',shots:['远景：朝阳映照山峰，水雾升起。','中景：从远处望见岩壁上的瀑布。','近景：飞流与水花，强调速度和落差。','想象：瀑布过渡为银河，回到山川。']},
 {film:'chunwang',work:'df-chunwang',title:'春望',scene:'757年春的长安诗意场景，城中草木繁盛，诗人凝望春花与归鸟，手中握着家书',evidence:'“国破山河在”“城春草木深”“感时花溅泪”“家书抵万金”',emotion:'忧国、思亲与克制的悲伤',boundary:'不把想象的街区当作长安考古复原，不以战斗奇观代替诗人的忧思。',verse:'故园消息隔江春，\n一纸灯前读到晨。\n窗外落花知客意，\n随风轻叩未归人。',shots:['远景：春日城郭与繁盛草木。','近景：花与归鸟，听见安静的环境声。','人物：诗人展开家书，镜头缓缓靠近。','收束：从家书抬望山河，留出沉默。']},
 {film:'chibi',work:'ss-nian',title:'念奴娇·赤壁怀古',scene:'黄州江边，苏轼临江怀古，乱石、惊涛与远处的月色相映，历史人物通过想象转场出现',evidence:'“大江东去”“乱石穿空”“惊涛拍岸”“一尊还酹江月”',emotion:'豪迈、感慨与自我开解',boundary:'黄州赤壁与赤壁之战古战场需要区分；周瑜画面标明为词人的历史想象。',verse:'江风吹散旧愁痕，\n一棹烟波过远村。\n不问浮名归何处，\n且邀明月共开樽。',shots:['远景：黄州江水奔流，乱石耸立。','细节：惊涛拍岸，水花化为画面转场。','想象：遥想周瑜，标明历史怀想。','回望：回到词人与江月，收束个人感慨。']}
];
const STUDIO_STORAGE='shixing-studio-demo-v1',STUDIO_LIMIT=30;
let studioWorkId='lb-lushan',studioMode='image',studioResult=null,galleryFilter='all',studioStorageAvailable=true;
function studioText(value,max=1800){return typeof value==='string'?value.slice(0,max):'';}
function studioWork(id=studioWorkId){return allWorks.find(w=>w.meta.id===id);}
function studioProfile(id=studioWorkId){const w=studioWork(id);return studioProfiles.find(p=>p.work===id)||studioProfiles[w?.a||0];}
function normalizeStudioRecord(record){
 if(!record||typeof record!=='object'||!studioWork(record.poemId)||!['image','video','poem'].includes(record.mode))return null;
 const clean={id:studioText(record.id,80),poemId:record.poemId,mode:record.mode,title:studioText(record.title,60),alias:studioText(record.alias,20)||'匿名同学',prompt:studioText(record.prompt),evidence:studioText(record.evidence,500),imagination:studioText(record.imagination,500),artifactText:studioText(record.artifactText,1000),createdAt:studioText(record.createdAt,40),feedback:Array.isArray(record.feedback)?record.feedback.slice(-10).map(x=>studioText(x,300)).filter(Boolean):[],origin:['mine','imported','example'].includes(record.origin)?record.origin:'imported'};
 return clean.id&&clean.prompt&&clean.title?clean:null;
}
function loadStudioState(){try{const raw=JSON.parse(localStorage.getItem(STUDIO_STORAGE)||'null');return {credits:Number.isInteger(raw?.credits)?Math.max(0,Math.min(20,raw.credits)):20,works:Array.isArray(raw?.works)?raw.works.slice(0,STUDIO_LIMIT).map(normalizeStudioRecord).filter(Boolean):[]};}catch{return {credits:20,works:[]};}}
let studioState=loadStudioState();
function studioMessage(message){$('studioMessage').textContent=message;}
function persistStudio(){try{localStorage.setItem(STUDIO_STORAGE,JSON.stringify(studioState));return true;}catch{studioStorageAvailable=false;studioMessage('浏览器暂不能保存到本机；请导出作品文件，避免关闭页面后丢失。');return false;}}
function refreshCredits(){$('credits').textContent=studioState.credits;$('galleryBadge').textContent=studioState.works.length;}
function activeStudioTab(tab){const gallery=tab==='gallery';$('galleryPanel').hidden=!gallery;$('composePanel').hidden=gallery;for(const [id,active]of [['composeTab',!gallery],['galleryTab',gallery]]){$(id).setAttribute('aria-selected',String(active));$(id).tabIndex=active?0:-1;}if(gallery)renderStudioGallery();}
function populateStudioWorks(){const author=+$('studioAuthor').value,works=allWorks.filter(w=>w.a===author);$('studioWork').innerHTML=works.map(w=>`<option value="${w.meta.id}">${escapeHtml(w.s[5])}</option>`).join('');if(!works.some(w=>w.meta.id===studioWorkId))studioWorkId=(studioProfiles[author]?.work)||works[0].meta.id;$('studioWork').value=studioWorkId;renderStudioSource();}
function renderStudioSource(){const w=studioWork();$('studioPoem').innerHTML=`<h3>${escapeHtml(w.s[5])}</h3><p class="studio-poem-meta">${people[w.a].name} · ${escapeHtml(w.s[0])} · ${escapeHtml(w.s[1])}<br>${escapeHtml(w.meta.role)} · ${escapeHtml(w.meta.kind)}</p><div class="studio-poem-text">${escapeHtml(w.s[6])}</div>`;$('studioQuestion').textContent=w.s[10];$('studioMap').href='index.html?work='+encodeURIComponent(w.meta.id);renderPromptExamples();fillStudioPrompt(0);studioResult=null;$('studioResult').hidden=true;}
function promptOptions(){return studioMode==='video'?['把诗句拆成四个镜头','从一个人物的视角拍摄','用转场表现诗意想象']:studioMode==='poem'?['借意象写一首四句诗','同一风景，换一种心情','写一首给今天的诗']:['从诗句里寻找画面','换一个观察视角','画出真实与想象的交界'];}
function renderPromptExamples(){$('promptExamples').innerHTML=promptOptions().map((t,i)=>`<button data-prompt-example="${i}">${t} ↗</button>`).join('');document.querySelectorAll('[data-prompt-example]').forEach(b=>b.onclick=()=>fillStudioPrompt(+b.dataset.promptExample));}
function makeStudioPrompt(index=0){
 const w=studioWork(),p=studioProfile(),exact=p.work===w.meta.id,quote=w.s[6].split('\n').filter(Boolean).slice(0,4).join(' / '),style=$('studioStyle').value,view=$('studioView').value;
 const basis=`创作依据：${people[w.a].name}《${w.s[5]}》。\n原文线索：${quote}\n时代与地点：${w.s[0]}，${w.s[1]}（${w.meta.role}）。`;
 const scene=exact?p.scene:`请从原文中提取具体意象，表现“${w.meta.focus||w.s[9]}”，不要照搬其他作品的场景。`;
 const approach=index===1?'换成一个人物的观察视角，写清看见、听见和感受到的细节。':index===2?'把文本直接写到的景物与艺术想象分开表达，并标注想象转场。':'先让每一个场景细节都能找到对应诗句。';
 if(studioMode==='video')return `${basis}\n任务：构思约60秒的诗意短片，采用${style}，${view}。\n场景：${scene}\n分镜：0—15秒建立环境；15—30秒聚焦意象；30—45秒表现情感变化；45—60秒回到原诗。写清镜头、朗诵、环境声与轻配乐。\n${approach}\n读图边界：${exact?p.boundary:'人物、服饰与建筑细节若无依据，请注明为艺术设想；诗中地点不能直接当作作者亲历。'}`;
 if(studioMode==='poem')return `${basis}\n任务：以原作的意象或情感为启发，构思一首四句的中文仿写诗，表达我自己的感受。${index===2?'把场景转到今天，但保留一个能与原诗对话的意象。':''}\n先说明借用了哪些意象，再提供仿写，并解释与原作的区别。不冒充诗人原作，不声称严格符合格律。\n${approach}\n我的表达方向：${exact?p.emotion:'用我自己的语言写出对这篇作品的理解'}。`;
 return `${basis}\n任务：构思一幅${style}场景图，${view}。\n场景：${scene}\n情感与光线：${exact?p.emotion:'根据原文选择情感与光线'}。保持清晰的前、中、后景，不添加现代道路、广告或无依据的战斗场面。\n${approach}\n读图边界：${exact?p.boundary:'明确区分原文直接描写的内容与我补充的想象，不把艺术画面当作史实复原。'}`;
}
function updatePromptCount(){$('promptCount').textContent=$('studioPrompt').value.length+' / 1800';}
function fillStudioPrompt(index){$('studioPrompt').value=makeStudioPrompt(index).slice(0,1800);updatePromptCount();}
function selectStudioMode(mode){studioMode=mode;document.querySelector('.style-row').hidden=mode==='poem';document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===mode)));$('previewHint').textContent=studioModes[mode].hint;$('previewCreation').innerHTML=`预览创作流程 <span>−${studioModes[mode].cost} 演示 Token</span>`;renderPromptExamples();fillStudioPrompt(0);studioResult=null;$('studioResult').hidden=true;}
function sampleCaption(record){const p=studioProfile(record.poemId),w=studioWork(record.poemId);return `内置参考：《${p.title}》${p.work!==w.meta.id?'（与当前所选篇目不同，仅供形式参考）':''}。不是根据你的提示词新生成的作品。`;}
function previewStudioCreation(){
 const prompt=$('studioPrompt').value.trim(),cost=studioModes[studioMode].cost;if(prompt.length<20){studioMessage('请至少写20个字，说明你想表达的场景、意象或情感。');$('studioPrompt').focus();return;}if(studioState.credits<cost){studioMessage('本次演示额度不足。点击右上方“演示 Token”，可恢复20点继续体验。');return;}
 studioState.credits-=cost;persistStudio();refreshCredits();const w=studioWork(),p=studioProfile();studioResult={id:crypto.randomUUID(),poemId:studioWorkId,mode:studioMode,prompt,title:'我眼中的《'+w.s[5]+'》',alias:'',evidence:'',imagination:'',artifactText:studioMode==='poem'?p.verse:'',createdAt:new Date().toISOString(),feedback:[],origin:'mine'};renderStudioResult();if(studioStorageAvailable)studioMessage(`已使用 ${cost} 个演示 Token，打开内置参考样例；未调用生成服务。`);$('studioResult').scrollIntoView({behavior:'smooth',block:'start'});
}
function renderStudioResult(){
 const r=studioResult,p=studioProfile(r.poemId),w=studioWork(r.poemId);$('studioResult').hidden=false;
 let sample=r.mode==='poem'?`<div class="sample-writing"><small>预写仿写范例 · 可修改 · 非诗人原作</small><label class="sr-only" for="artifactText">修改仿写诗</label><textarea id="artifactText" rows="5" maxlength="1000">${escapeHtml(r.artifactText)}</textarea></div>`:`<div class="sample-visual"><img src="assets/films/${p.film}-poster.jpg" alt="《${p.title}》内置参考场景，非本次生成">${r.mode==='video'?'<button id="studioPlayFilm">▶ 播放参考影片</button>':''}</div>`;
 if(r.mode==='video')sample+=`<div class="storyboard-mini" aria-label="内置参考分镜">${p.shots.map((text,i)=>`<div><small>${i*15}—${(i+1)*15}秒 · 构思参考</small><p>${text}</p></div>`).join('')}</div>`;
 $('studioResult').innerHTML=`<div class="result-top"><div><p class="eyebrow">从示例到自己的表达</p><h2 id="resultHeading">给想象，写一段说明</h2><p>保存提示词与阅读发现，组成一张可以交流的作品卡。</p></div><span class="sample-badge">内置样例 · 非实时 AI 生成</span></div><div class="result-layout"><div>${sample}<p class="sample-caption">${escapeHtml(sampleCaption(r))}${r.mode==='poem'?'仿写只作形式练习，未做格律校验。':''}</p></div><form class="result-reflection" id="saveStudioForm"><div class="reflection-name"><div><label for="workTitle">作品标题</label><input id="workTitle" maxlength="60" required value="${escapeHtml(r.title)}"></div><div><label for="workAlias">我的署名（可用化名）</label><input id="workAlias" maxlength="20" placeholder="匿名同学" value="${escapeHtml(r.alias)}"></div></div><label for="workEvidence">我依据了哪些诗句？ <span>必填</span></label><textarea id="workEvidence" rows="3" maxlength="500" required placeholder="引用一句原诗，说说它怎样影响了你的构思。">${escapeHtml(r.evidence)}</textarea><label for="workImagination">哪些是我补充的想象？ <span>必填</span></label><textarea id="workImagination" rows="3" maxlength="500" required placeholder="说明你增加的颜色、人物、镜头或情感，与原文有什么联系。">${escapeHtml(r.imagination)}</textarea><div class="save-row"><p>基于《${escapeHtml(w.s[5])}》<br>只保存到本机；不会公开发布。</p><button type="submit" class="studio-primary" id="saveStudioWork">保存到我的作品 →</button></div></form></div>`;
 if($('studioPlayFilm'))$('studioPlayFilm').onclick=()=>playFilm(p.film);$('saveStudioForm').onsubmit=e=>{e.preventDefault();saveStudioResult();};
}
function saveStudioResult(){
 const r=studioResult;if(!r)return;r.title=$('workTitle').value.trim();r.alias=$('workAlias').value.trim()||'匿名同学';r.evidence=$('workEvidence').value.trim();r.imagination=$('workImagination').value.trim();if(!r.title||!r.evidence||!r.imagination){studioMessage('请写下作品标题、诗句依据和想象说明，再保存。');return;}if($('artifactText'))r.artifactText=$('artifactText').value.trim();if(r.mode==='poem'&&!r.artifactText){studioMessage('请先填写你的仿写内容。');return;}const existing=studioState.works.findIndex(w=>w.id===r.id);if(existing<0&&studioState.works.length>=STUDIO_LIMIT){studioMessage('本机最多保存30张作品卡。请先导出备份，再在作品详情中删除不需要的卡片。');return;}if(existing>=0)studioState.works[existing]={...r};else studioState.works.unshift({...r});const saved=persistStudio();refreshCredits();galleryFilter='mine';activeStudioTab('gallery');if(saved)studioMessage('作品卡已保存到本机。可以导出交给同学，或打开详情互评。');$('galleryTab').focus();
}
function studioExamples(){return studioProfiles.map((p,i)=>({id:'class-example-'+i,poemId:p.work,mode:['image','video','poem'][i],title:['把飞瀑画成银河','春天为什么让人落泪','借江月，写自己的心情'][i],alias:'课堂范例',prompt:`围绕《${p.title}》，以${p.evidence}为依据，表现${p.emotion}。${p.boundary}`,evidence:'我的文本线索是'+p.evidence+'，画面要服务于诗中的情感。',imagination:p.boundary+'画面与仿写是帮助理解的艺术练习。',artifactText:i===2?p.verse:'',origin:'example',createdAt:'',feedback:[]}));}
function allStudioRecords(){return [...studioState.works,...studioExamples()];}
function renderStudioGallery(){document.querySelectorAll('[data-gallery-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.galleryFilter===galleryFilter)));const records=allStudioRecords().filter(r=>galleryFilter==='all'||r.origin===galleryFilter);$('studioGallery').innerHTML=records.length?records.map(r=>{const w=studioWork(r.poemId),p=studioProfile(r.poemId),origin={mine:'我保存的',imported:'同学导入',example:'课堂范例'}[r.origin];return `<article class="studio-card">${r.mode==='poem'?`<div class="card-verse">${escapeHtml(r.artifactText||p.verse)}</div>`:`<img src="assets/films/${p.film}-poster.jpg" alt="《${p.title}》内置参考${r.mode==='video'?'影片':'画面'}" loading="lazy">`}<div class="studio-card-copy"><div class="studio-card-type"><span>${studioModes[r.mode].name} · 演示</span><span>${origin}</span></div><h3>${escapeHtml(r.title)}</h3><p>${escapeHtml(r.evidence.slice(0,90))}</p><p><small>${escapeHtml(r.alias)} · 《${escapeHtml(w.s[5])}》</small></p><button data-open-studio-work="${escapeHtml(r.id)}">看构思，聊理解 <span>→</span></button></div></article>`;}).join(''):`<div class="gallery-empty"><h3>${galleryFilter==='imported'?'等一张同学的作品卡':'还没有保存的作品'}</h3><p>${galleryFilter==='imported'?'点击上方“导入同学作品”，打开对方导出的 JSON 文件。':'先在创作台写下提示词和阅读发现，再保存到这里。'}</p></div>`;document.querySelectorAll('[data-open-studio-work]').forEach(b=>b.onclick=()=>openStudioRecord(b.dataset.openStudioWork));}
function downloadStudioRecords(records){if(!records.length){studioMessage('暂无可导出的作品。先保存一张作品卡，再来交流。');return;}const data={kind:'shixing-poetry-studio',version:1,mode:'demo',note:'包含学生提示词、阅读说明和内置样例引用；不是实时AI生成文件。',works:records.map(({origin,...r})=>r)};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='诗意创作坊-作品交流.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);studioMessage('作品交流文件已导出。同学可以在自己的创作坊导入查看。');}
function importStudioData(text){
 const data=JSON.parse(text);if(data?.kind!=='shixing-poetry-studio'||data.version!==1||data.mode!=='demo'||!Array.isArray(data.works)||!data.works.length||data.works.length>30)throw Error('文件格式不匹配，请导入创作坊导出的作品文件（每次最多30张）。');
 const records=data.works.map(normalizeStudioRecord);if(records.some(r=>!r))throw Error('文件包含不完整的作品，未导入。请让同学重新导出。');if(studioState.works.length+records.length>STUDIO_LIMIT)throw Error('导入后将超过本机30张作品上限。请先导出备份并整理作品。');
 const imported=records.map(r=>({...r,id:crypto.randomUUID(),origin:'imported'}));studioState.works.unshift(...imported);const saved=persistStudio();refreshCredits();galleryFilter='imported';activeStudioTab('gallery');if(saved)studioMessage(`已导入 ${imported.length} 张作品卡，演示额度未改变。`);return imported.length;
}
function openStudioRecord(id){
 const r=allStudioRecords().find(w=>w.id===id);if(!r)return;const w=studioWork(r.poemId),p=studioProfile(r.poemId);showModal(`<div class="work-reader"><p class="eyebrow">${r.origin==='example'?'课堂范例 · 非真实学生投稿':'作品交流 · 本机保存'}</p><h2>${escapeHtml(r.title)}</h2><p class="reader-meta">${escapeHtml(r.alias)} · 灵感来自${people[w.a].name}《${escapeHtml(w.s[5])}》</p><span class="sample-badge">交互演示 · 参考素材非本次生成</span>${r.mode==='poem'?`<div class="work-original">${escapeHtml(r.artifactText||p.verse)}</div>`:`<img src="assets/films/${p.film}-poster.jpg" alt="《${p.title}》内置参考素材">`}<p class="sample-caption">${escapeHtml(sampleCaption(r))}${r.mode==='poem'?'仿写练习，非诗人原作。':''}</p><h3>我依据的诗句</h3><p>${escapeHtml(r.evidence)}</p><h3>我补充的想象</h3><p>${escapeHtml(r.imagination)}</p><h3>我的提示词</h3><pre>${escapeHtml(r.prompt)}</pre><div class="work-tools"><button id="exportStudioRecord">导出这张作品卡 ↓</button>${r.mode==='video'?'<button id="recordFilm">播放内置参考影片</button>':''}<a href="index.html?work=${encodeURIComponent(r.poemId)}">回原诗与足迹核对 ↗</a>${r.origin!=='example'?'<button id="deleteStudioRecord">删除本机卡片</button>':''}</div><div class="peer-feedback"><h3>带着诗句，给一条反馈</h3><p>可以从“我在原诗中找到了……”或“这个想象让我想到……”开始。</p><div id="studioFeedbackList">${renderStudioFeedback(r)}</div><label for="studioFeedback">我的反馈（只保存在本机，可随作品导出）</label><textarea id="studioFeedback" maxlength="300" rows="3" placeholder="引用一个细节，再提出一个问题。"></textarea><button id="saveStudioFeedback">保存反馈</button><p id="feedbackMessage" role="status"></p></div></div>`);
 $('exportStudioRecord').onclick=()=>downloadStudioRecords([r]);if($('recordFilm'))$('recordFilm').onclick=()=>playFilm(p.film);if($('deleteStudioRecord'))$('deleteStudioRecord').onclick=()=>{studioState.works=studioState.works.filter(x=>x.id!==r.id);persistStudio();refreshCredits();renderStudioGallery();$('modal').close();studioMessage('本机卡片已删除。若已导出，仍可通过文件重新导入。');};
 $('saveStudioFeedback').onclick=()=>{const text=$('studioFeedback').value.trim();if(!text){$('feedbackMessage').textContent='请先写下一条具体反馈。';return;}let target=studioState.works.find(x=>x.id===r.id);if(!target){if(studioState.works.length>=STUDIO_LIMIT){$('feedbackMessage').textContent='本机作品已达上限，请先整理作品。';return;}target={...r,id:crypto.randomUUID(),origin:'mine',feedback:[]};studioState.works.unshift(target);r.feedback=target.feedback;}target.feedback.push(text);target.feedback=target.feedback.slice(-10);r.feedback=target.feedback;const feedbackSaved=persistStudio();refreshCredits();$('studioFeedbackList').innerHTML=renderStudioFeedback(target);$('studioFeedback').value='';$('feedbackMessage').textContent=feedbackSaved?'反馈已保存到本机。导出作品卡即可把反馈交给同学。':'反馈暂存在当前页面，请导出作品卡保存。';};
}
function renderStudioFeedback(r){return r.feedback.length?r.feedback.map(t=>`<p class="work-feedback">${escapeHtml(t)}</p>`).join(''):'<p class="sample-caption">还没有反馈。先分享你的阅读发现。</p>';}
function creditStudioInfo(){showModal('<p class="eyebrow">演示 Token · 体验说明</p><h2>把创作机会，用在好问题上</h2><p>当前每台浏览器有20点演示额度：图片预览2点、视频参考6点、仿写范例1点。这是课堂交互示意，与真实模型的计费 Token 不同。</p><p>本站未接入生成模型，不需要 API 密钥，也不会产生费用。修改提示词会保存为你的创作构思，但不会改变内置图片、影片或仿写范例。</p><p>作品与反馈仅保存在本机；通过导出、导入文件交流，尚未连接班级共享空间。</p><button class="studio-primary" id="resetStudioCredits">恢复20点演示额度</button>');$('resetStudioCredits').onclick=()=>{studioState.credits=20;persistStudio();refreshCredits();$('modal').close();studioMessage('已恢复20点演示额度，已保存的作品不受影响。');};}
$('close').onclick=()=>$('modal').close();$('modal').onclick=e=>{if(e.target===$('modal'))$('modal').close();};
$('composeTab').onclick=()=>activeStudioTab('compose');$('galleryTab').onclick=()=>activeStudioTab('gallery');for(const id of ['composeTab','galleryTab'])$(id).onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const gallery=e.key==='End'||(e.key!=='Home'&&id==='composeTab');activeStudioTab(gallery?'gallery':'compose');$(gallery?'galleryTab':'composeTab').focus();}};
$('studioAuthor').onchange=()=>{studioWorkId=studioProfiles[+$('studioAuthor').value].work;populateStudioWorks();};$('studioWork').onchange=()=>{studioWorkId=$('studioWork').value;renderStudioSource();};$('studioRead').onclick=()=>readWork(studioWorkId);document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>selectStudioMode(b.dataset.mode));$('studioPrompt').oninput=updatePromptCount;
$('studioStyle').onchange=()=>studioMessage('风格已选择。点击上方任一示例，可把新风格填入提示词；已编辑的文字会保留。');$('studioView').onchange=()=>studioMessage('视角已选择。点击上方任一示例，可把新视角填入提示词；已编辑的文字会保留。');$('previewCreation').onclick=previewStudioCreation;$('creditInfo').onclick=creditStudioInfo;
$('importWork').onclick=()=>$('importFile').click();$('importFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>300000)throw Error('作品文件过大，请选择小于300KB的创作坊交流文件。');importStudioData(await file.text());}catch(error){studioMessage(error instanceof SyntaxError?'文件不是有效的 JSON，请选择创作坊导出的作品交流文件。':error.message);}finally{e.target.value='';}};
$('exportAll').onclick=()=>downloadStudioRecords(studioState.works.filter(r=>r.origin==='mine'));document.querySelectorAll('[data-gallery-filter]').forEach(b=>b.onclick=()=>{galleryFilter=b.dataset.galleryFilter;renderStudioGallery();});
$('studioTeacher').onclick=()=>showModal('<p class="eyebrow">课堂创作任务 · 建议20分钟</p><h2>先读懂，再把想象说清楚</h2><ol><li><strong>读诗找证据（4分钟）</strong>：圈出两处意象或关键词，说明情感与时代背景。</li><li><strong>写提示词（5分钟）</strong>：选择画面、分镜或仿写，写清文本依据和想象的边界。</li><li><strong>看例并修改（5分钟）</strong>：借内置范例讨论提示词是否具体；仿写可以直接修改，避免把范例当作诗人原作。</li><li><strong>作品交流（6分钟）</strong>：保存并导出作品卡，互相导入。每人提出一个有诗句依据的问题，再带着反馈修改。</li></ol><h3>观察学生学到了什么</h3><p>能否指出原诗证据？画面与情感是否一致？能否区分史实、诗意和自己的设想？仿写有没有自己的表达？评价不以画面华丽程度为主。</p><p>当前为交互演示：预览使用内置素材，不调用AI；本机保存与文件交换替代在线班级共享。</p>');
const studioRequested=new URLSearchParams(location.search).get('work');if(studioWork(studioRequested))studioWorkId=studioRequested;$('studioAuthor').value=String(studioWork().a);populateStudioWorks();refreshCredits();renderStudioGallery();initCinema();
